/* Read-only first-dose dashboard from existing encounter evidence. */
(function(root){const encounter=root.FNEncounter||(typeof require==='function'?require('./encounter-core.js'):null);
function build(visits,now=Date.now()){const rows=visits.filter(v=>v.snapshot?.recordType!=='protocol'&&v.snapshot?.dynamic?.mode!=='simulation').map(v=>{const d=encounter.fromVisit(v),p=encounter.project(d,now),ready=d.encounter?.milestones?.ready,proposal=d.proposal;const next=p.clock==='excluded'?'Continue documented care':!p.doseId&&p.remaining===null?'Verify triage time':p.doseId?p.appropriate==='Unknown'?'Review first-dose appropriateness':'Continue reassessment':!v.snapshot.dynamic?'Start encounter follow-up':!proposal?'Physician plan review':proposal.pharmacy?.decision!=='approve'?'Pharmacy review':!ready?'Drug preparation / readiness':'Document actual administration';return{...p,visitId:v.id,label:d.label||v.case_code,triageAt:p.milestones[0].at,doseAt:p.milestones[4].at,next,tracked:!!v.snapshot.dynamic}});const active=rows.filter(r=>!r.doseId&&r.clock!=='excluded'),timed=active.filter(r=>r.remaining!==null);const summary=encounter.summarize(visits,now);return{rows,summary,waiting:timed.length,dueSoon:timed.filter(r=>r.remaining>=0&&r.remaining<=15).length,overdue:timed.filter(r=>r.remaining<0).length,missingTriage:active.filter(r=>r.remaining===null).length,doseDocumented:rows.filter(r=>r.doseId).length,reviewNeeded:rows.filter(r=>r.doseId&&r.appropriate==='Unknown').length}}
function filter(rows,mode){const result=rows.filter(r=>mode==='all'||mode==='overdue'&&r.clock==='overdue'||mode==='due'&&!r.doseId&&r.remaining!==null&&r.remaining>=0&&r.remaining<=15||mode==='waiting'&&!r.doseId&&r.remaining!==null&&r.clock!=='excluded'||mode==='gaps'&&r.gaps.length||mode==='dosed'&&r.doseId);return result.sort((a,b)=>{const priority=r=>r.clock==='overdue'?0:r.clock==='due_soon'?1:r.clock==='running'?2:r.clock==='triage_unknown'?3:4;return priority(a)-priority(b)||(a.remaining??Infinity)-(b.remaining??Infinity)})}
const api={build,filter};root.FNTTACore=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
